// Static article content for the Journal/Blog.
// To add or edit posts, simply edit this file — the website will update on save.

export const ARTICLES = [
  {
    slug: "nikah-registration-delhi-process",
    title: "Nikah Registration in Delhi — Complete Legal Process",
    excerpt:
      "How to convert your Nikah into a legally recognised marriage with a registered certificate — under the Special Marriage Act or the Delhi Compulsory Registration Order.",
    category: "Nikah",
    author: "JurisRoots Chambers",
    read_time: "8 min read",
    date: "2026-05-10",
    cover:
      "https://images.unsplash.com/photo-1589994965851-a8f479c573a9?auto=format&fit=crop&w=1200&q=80",
    body: [
      { h: "What is Nikah registration?" },
      { p: "A Nikah, in Indian law, is a valid marriage under Muslim Personal Law from the moment it is solemnised. However, for almost every modern use — passport, visa, joint bank account, foreign embassy, or government records — you need a marriage certificate issued by a civil registrar. That conversion of a religious nikah into a registered civil marriage is what 'Nikah registration' refers to." },
      { h: "Two legal routes available in Delhi" },
      { list: [
        "Special Marriage Act, 1954 — civil registration available to any couple regardless of religion. A 30-day notice applies.",
        "Delhi Compulsory Registration of Marriage Order, 2014 — allows registration of an already-solemnised marriage (including a nikah) within 60 days at the local SDM office.",
      ]},
      { h: "Documents required" },
      { list: [
        "Nikahnama (Urdu, English, or both)",
        "Aadhaar and PAN of both spouses",
        "Address proof for both",
        "Two passport-size photos each",
        "Age proof — 10th certificate, birth certificate, or passport",
        "Two adult witnesses with valid ID",
      ]},
      { h: "Step-by-step process" },
      { list: [
        "Nikahnama vetting and translation (if in Urdu)",
        "Joint affidavit drafting",
        "Application filing at the SDM office of jurisdiction",
        "Witness appearance and signing of the register",
        "Certificate issuance — typically within 7 working days",
      ]},
    ],
  },
  {
    slug: "arya-samaj-marriage-delhi",
    title: "Arya Samaj Marriage in Delhi — Same-Week Legal Registration",
    excerpt:
      "A Vedic ceremony at an Arya Samaj Mandir followed by court registration — fully legal, fast, and a popular choice for couples seeking dignity without the SMA notice period.",
    category: "Arya Samaj",
    author: "JurisRoots Chambers",
    read_time: "7 min read",
    date: "2026-05-08",
    cover:
      "https://images.unsplash.com/photo-1505664194779-8beaceb93744?auto=format&fit=crop&w=1200&q=80",
    body: [
      { h: "Is an Arya Samaj marriage legal?" },
      { p: "Yes — fully. Arya Samaj marriages are recognised under the Arya Marriage Validation Act, 1937 and are eligible for registration under the Hindu Marriage Act, 1955. The Supreme Court has repeatedly upheld their validity. The certificate issued by the Arya Samaj Mandir is the basis for civil registration at the SDM office." },
      { h: "Who is it suitable for?" },
      { list: [
        "Hindu couples seeking a fast, dignified ceremony without the 30-day SMA notice",
        "Inter-caste Hindu couples",
        "Couples whose families approve in principle but want a private ceremony",
        "Inter-faith couples where one party converts to Hinduism by Vedic shuddhi",
      ]},
      { h: "The ceremony" },
      { p: "A short Vedic ceremony — havan, saat phere (saptapadi), and the recitation of Vedic mantras — typically concluded in 60–90 minutes. The Mandir then issues an Arya Samaj marriage certificate signed by the Mandir's authorised priest." },
      { h: "Court registration that follows" },
      { p: "The Arya Samaj certificate, along with photographs and ID proof, is filed at the SDM office under the Hindu Marriage Act, 1955. A registered marriage certificate is issued — usually within the same week. This is the certificate accepted by passport offices, embassies, and banks." },
    ],
  },
  {
    slug: "court-marriage-delhi-complete-guide",
    title: "Court Marriage in Delhi: A Complete 2026 Guide",
    excerpt:
      "From eligibility and jurisdiction to the 30-day notice period — everything a Delhi couple needs to know before filing.",
    category: "Guides",
    author: "DCMS Chambers",
    read_time: "9 min read",
    date: "2026-01-12",
    cover:
      "https://images.unsplash.com/photo-1625728684164-72d61b14afeb?crop=entropy&cs=srgb&fm=jpg&ixid=M3w4NjA1NTZ8MHwxfHNlYXJjaHwyfHxpbmRpYW4lMjBhcmNoaXRlY3R1cmUlMjBzYW5kc3RvbmUlMjBkZXRhaWxzfGVufDB8fHx8MTc3Njk4MjI4OHww&ixlib=rb-4.1.0&q=85",
    body: [
      { h: "Who is a court marriage for?" },
      {
        p: "Any two consenting adults who wish to marry under a civil framework — irrespective of religion, caste, or community — can opt for a court marriage in Delhi. It is particularly useful for inter-faith and inter-caste couples, couples seeking a minimalist legal ceremony, and NRIs needing a registered certificate for visa or immigration purposes.",
      },
      { h: "Applicable laws" },
      {
        p: "Most court marriages in Delhi are solemnised under the Special Marriage Act, 1954. Couples already married under Hindu rites can register under the Hindu Marriage Act, 1955. The Special Marriage Act is the go-to statute for civil ceremonies with no faith-based requirement.",
      },
      { h: "Eligibility checklist" },
      {
        list: [
          "Both parties must be of legal age — 21 for the groom, 18 for the bride.",
          "Neither party should have a living spouse at the time of filing.",
          "Both must be of sound mind and capable of giving valid consent.",
          "The parties must not fall within prohibited degrees of relationship.",
        ],
      },
      { h: "The 30-day notice" },
      {
        p: "Under the Special Marriage Act, a written notice of the intended marriage must be filed with the Marriage Officer of the district where either party has resided for at least 30 days prior. The notice is then displayed for 30 days to invite any objections. This waiting period is statutory and cannot be waived — Tatkal services expedite the paperwork but not the notice itself.",
      },
      { h: "Jurisdiction matters" },
      {
        p: "The SDM office is chosen by residence, not by preference. If one partner has lived in South Delhi for 45 days, for example, the South SDM office becomes the filing jurisdiction. Errors in jurisdiction are the most common reason applications get returned.",
      },
      { h: "After the notice period" },
      {
        p: "If no objections are raised, the couple appears before the Marriage Officer along with three witnesses (each with valid ID and address proof). The marriage is solemnised, the register is signed, and a certified certificate is issued the same day.",
      },
      { h: "A word on confidentiality" },
      {
        p: "The notice is legally required to be displayed publicly. However, for couples concerned about privacy, an experienced advocate can guide filing in jurisdictions where public display is minimal. Discretion is part of the work.",
      },
    ],
  },
  {
    slug: "special-marriage-act-vs-hindu-marriage-act",
    title: "Special Marriage Act vs Hindu Marriage Act — which one applies to you?",
    excerpt:
      "Choosing the right Act is the single biggest decision in any registration. A side-by-side comparison.",
    category: "Legal Explainer",
    author: "DCMS Chambers",
    read_time: "6 min read",
    date: "2026-01-04",
    cover:
      "https://images.pexels.com/photos/48148/document-agreement-documents-sign-48148.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940",
    body: [
      { h: "The Hindu Marriage Act, 1955" },
      {
        p: "The HMA applies to Hindus, Buddhists, Jains, and Sikhs. It is intended for registering a marriage that has already been solemnised under religious rites. Because the ceremony has already occurred, the registration itself is largely administrative and can often be completed within a week.",
      },
      { h: "The Special Marriage Act, 1954" },
      {
        p: "SMA is a secular statute, available to any citizen irrespective of religion. Under SMA, the Marriage Officer actually solemnises the marriage (not a priest), meaning the legal ceremony happens in the office itself. A 30-day public notice is mandated.",
      },
      { h: "When to choose which" },
      {
        list: [
          "Inter-faith couple → Special Marriage Act (mandatory, in practice).",
          "Both Hindu, already married by rites → Hindu Marriage Act (faster).",
          "Both Hindu, want a civil ceremony only → Special Marriage Act.",
          "NRI / OCI / foreign national involved → Special Marriage Act (broader recognition abroad).",
        ],
      },
      { h: "Document differences" },
      {
        p: "Under HMA, you additionally submit wedding photographs and an invitation card (where available). Under SMA, no wedding photos are required because the ceremony will take place at the SDM office itself.",
      },
      { h: "Timeline at a glance" },
      {
        list: [
          "HMA: 5–10 working days end-to-end.",
          "SMA: 30–45 days (due to the mandated notice).",
        ],
      },
    ],
  },
  {
    slug: "documents-required-checklist",
    title: "The master documents checklist — what to prepare before your first visit",
    excerpt:
      "A concise, no-nonsense checklist used by our chamber for every case we onboard.",
    category: "Checklist",
    author: "DCMS Chambers",
    read_time: "4 min read",
    date: "2025-12-20",
    cover:
      "https://images.pexels.com/photos/5993559/pexels-photo-5993559.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940",
    body: [
      { h: "Identity & age" },
      {
        list: [
          "Aadhaar card (both parties)",
          "PAN card (both parties)",
          "10th class certificate OR birth certificate OR passport — any one for age proof",
        ],
      },
      { h: "Address" },
      {
        list: [
          "Aadhaar / voter ID / passport (any one)",
          "A recent utility bill (electricity/gas) not older than 3 months",
          "Rent agreement or ownership proof of current residence",
        ],
      },
      { h: "Photographs" },
      {
        list: [
          "6 passport-size photos of each partner",
          "2 post-card size joint photos",
          "Wedding ceremony photo (only for HMA registration)",
        ],
      },
      { h: "Affidavits" },
      {
        list: [
          "Affidavit of marital status (single/divorced/widowed)",
          "Declaration of nationality and religion",
          "Joint affidavit of marriage (HMA only)",
        ],
      },
      { h: "Witnesses" },
      {
        p: "You will need three witnesses on the day of solemnisation. Each witness must carry their own ID proof, address proof, and two passport-size photographs. If you cannot arrange witnesses, speak to us — arranging compliant witnesses is part of our standard service.",
      },
    ],
  },
  {
    slug: "nri-marriage-registration-delhi",
    title: "NRI marriage registration: what to know before you fly",
    excerpt:
      "Attestations, Power of Attorney, and the one mistake that adds 4 weeks to most NRI cases.",
    category: "NRI",
    author: "DCMS Chambers",
    read_time: "7 min read",
    date: "2025-12-08",
    cover:
      "https://images.pexels.com/photos/36760656/pexels-photo-36760656.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940",
    body: [
      { h: "Why NRI cases are different" },
      {
        p: "NRI and OCI cases involve three additional layers: (1) apostille attestation for foreign-issued documents, (2) MEA attestation for Indian-issued documents that will travel abroad, and (3) embassy or consulate liaison when one party cannot travel to India in time for solemnisation.",
      },
      { h: "The Power of Attorney option" },
      {
        p: "Where one partner cannot be physically present, a specific, registered Power of Attorney can allow representation for most procedural steps — except solemnisation, which still requires personal presence under the Special Marriage Act.",
      },
      { h: "The one mistake that delays most NRI cases" },
      {
        p: "Submitting the 30-day residence proof of the NRI partner. Many couples assume the NRI's Indian address on Aadhaar counts — it often does not if the NRI has been abroad continuously. We guide clients to structure residence proof correctly before filing to avoid a 4–6 week delay.",
      },
      { h: "Documents unique to NRI cases" },
      {
        list: [
          "Current passport + latest visa stamps",
          "OCI card (if applicable)",
          "Apostille or embassy-attested affidavit of marital status",
          "Proof of continuous stay for 30 days (if SMA)",
        ],
      },
    ],
  },
  {
    slug: "tatkal-marriage-registration-how-fast",
    title: "Tatkal marriage registration — how fast can 'fast' really be?",
    excerpt:
      "A practical look at the 24–48 hour option: what it includes, what it can't, and who it's for.",
    category: "Fast-Track",
    author: "DCMS Chambers",
    read_time: "5 min read",
    date: "2025-11-28",
    cover:
      "https://images.unsplash.com/photo-1625728684164-72d61b14afeb?crop=entropy&cs=srgb&fm=jpg&ixid=M3w4NjA1NTZ8MHwxfHNlYXJjaHwyfHxpbmRpYW4lMjBhcmNoaXRlY3R1cmUlMjBzYW5kc3RvbmUlMjBkZXRhaWxzfGVufDB8fHx8MTc3Njk4MjI4OHww&ixlib=rb-4.1.0&q=85",
    body: [
      { h: "What Tatkal actually means" },
      {
        p: "Tatkal marriage registration refers to expedited processing under the Hindu Marriage Act (not SMA, which has an unwaivable 30-day notice). For couples already married by rites, Tatkal can deliver a certified marriage certificate in 24 to 48 hours.",
      },
      { h: "Who it's for" },
      {
        list: [
          "Couples with imminent visa interviews or travel dates",
          "Partners relocating for employment where marital status affects spouse visas",
          "Cases requiring urgent documentation for joint bank accounts or property",
        ],
      },
      { h: "What we handle" },
      {
        list: [
          "Priority SDM slot coordination",
          "Same-day affidavit drafting and notarisation",
          "Expedited witness arrangements",
          "Certificate collection, often the same day",
        ],
      },
      { h: "Honest caveats" },
      {
        p: "Tatkal cannot override statutory notice periods. Couples under the Special Marriage Act cannot be 'fast-tracked' past the 30-day notice, regardless of fee. If speed is the priority and HMA is not an option, planning around the notice is essential.",
      },
    ],
  },
];

export function getArticleBySlug(slug) {
  return ARTICLES.find((a) => a.slug === slug);
}
